    # This is equivalent to comparing y * ln(x) and x * ln(y),
    # or comparing ln(x)/x and ln(y)/y.
    # Let f(t) = ln(t)/t. The derivative f'(t) = (1 - ln(t))/t^2.
    # f(t) increases for 0 < t < e and decreases for t > e (e ≈ 2.718).

    if x == y:
        # If x and y are equal, x^y is obviously equal to y^x.
        print('=')
    elif x == 1:
        # 1^y = 1, and y^1 = y. Since y > 1 (because x != y), 1 < y.
