    elif y == 1:
        # x^1 = x, and 1^x = 1. Since x > 1 (because x != y), x > 1.
        print('>')
    elif x == 2:
        # Special cases for x = 2:
        # 2^1 = 2, 1^2 = 1 (handled by y == 1)
        # 2^2 = 4, 2^2 = 4 (handled by x == y)
