    line3 = sys.stdin.readline()
    if not line3:
        return
    try:
        p = int(line3.strip())
    except ValueError:
        return

    # dp[k][s] will store the number of subsets of size k with total sum s.
    # The constraints are n <= 50 and p <= 50.
    # We only need to track sums up to p.
    dp = [[0] * (p + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    # Iterate through each guest's size to populate the DP table
    for size in a:
        for k in range(n, 0, -1):
            for s in range(p, size - 1, -1):
                dp[k][s] += dp[k - 1][s - size]

    # The expected number of guests is E[X] = sum_{k=1 to n} P(X >= k),
    # where X is the number of guests admitted.
    # X >= k if and only if the first k guests in the random permutation fit at the table.
    # The probability P(X >= k) = (number of subsets of size k with sum <= p) / (total subsets of size k).

    expected_value = 0.0
    for k in range(1, n + 1):
        # Number of subsets of size k with sum <= p
        count_le_p = sum(dp[k][s] for s in range(p + 1))

        # Total number of subsets of size k is nCr(n, k)
        total_subsets = math.comb(n, k)

        if total_subsets > 0:
            expected_value += count_le_p / total_subsets

    # Print the result with sufficient precision
    print(f"{expected_value:.10f}")

